#!/usr/bin/env python3
# luxarch:luxpm-record-commit hook v5 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Record each new commit in a local ledger so it can't be forgotten in LuxPM.

House rule: ALL work is tracked in LuxPM. An instruction alone slips mid-task, so this makes
it mechanical. Pairs with luxpm-stop-guard.py (refuses to end the turn while the ledger has
unlogged commits) and luxpm-clear-ledger.py (empties it when you log to LuxPM).

PostToolUse(Bash): when a `git commit` produced a NEW HEAD, append it and surface a reminder.

The HEAD read is the checkout git committed in: the event's `cwd` (the agent's issue worktree), or
the directory a `git -C <dir> commit` names, read from the command as argv (`_cmdtext.git_calls`,
so a commit inside `bash -c` counts too). The ledger is the main checkout's, so it outlives the
worktree. A `git commit` that failed leaves HEAD where it was, so only a commit that ran is
recorded.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import MalformedEvent, git_calls
from _ledger import (
    event_command,
    event_cwd,
    git_at,
    record_session_commit,
    session_id,
    tree_dir,
    update_ledger,
)


def _commit_dirs(cmd: str) -> list[Path]:
    """Where each `git commit` in `cmd` ran: its `-C` directory, else the agent's checkout."""
    try:
        calls = [g for g in git_calls(cmd) if g.sub == "commit"]
    except MalformedEvent:
        calls = []
    if not calls:
        return [tree_dir()] if re.search(r"\bgit\s+commit\b", cmd) else []
    dirs = [event_cwd() / g.cwd if g.cwd else tree_dir() for g in calls]
    return list(dict.fromkeys(dirs))


def _record(where: Path) -> None:
    # A `git commit` that failed (nothing staged, a hook refused it) leaves HEAD where it was, and
    # recording that would claim the commit it points at, possibly another session's. A commit that
    # ran is HEAD's last reflog entry: `commit: …`, `commit (amend): …`, `commit (initial): …`.
    if not git_at(where, "reflog", "-1", "--format=%gs", "HEAD").startswith("commit"):
        return
    sha = git_at(where, "rev-parse", "--short", "HEAD")
    subject = git_at(where, "log", "-1", "--pretty=%s")
    # The commit's own time, so the link can carry `committed_at`: without it LuxPM cannot know a
    # commit's age, and an old sha linked as evidence becomes the sync receipt's anchor.
    committed_at = git_at(where, "log", "-1", "--format=%cI")
    if not sha:
        return
    # Whose commit this is, for the push guard: two agents in one tree must each be held to their
    # own unpushed work, never to the other's.
    record_session_commit(git_at(where, "rev-parse", "HEAD"), subject)
    issue = re.search(r"\b([A-Z][A-Z0-9]+-\d+)\b", subject)
    # Stamped with the SESSION: a commit belongs to one agent, and another agent must neither be
    # blocked by it nor log it on that agent's behalf (which would land wrong commits on someone
    # else's ticket).
    entry: dict[str, object] = {
        "sha": sha,
        "subject": subject,
        "committed_at": committed_at,
        "issue": issue.group(1) if issue else None,
        "session": session_id(),
    }
    known: list[bool] = []

    def add(entries: list[dict[str, object]]) -> list[dict[str, object]]:
        known.append(any(e.get("sha") == sha for e in entries))
        return entries if known[0] else [*entries, entry]

    entries = update_ledger(
        add
    )  # one locked step: a concurrent session's entry is never lost
    if known[0]:
        return
    print(
        f"LuxPM: recorded {sha} ({subject[:60]}). Log the work to LuxPM before ending the "
        f"turn — {len(entries)} commit(s) pending.",
        file=sys.stderr,
    )


def main() -> int:
    for where in _commit_dirs(event_command()):
        _record(where)
    return 0


sys.exit(main())
